// Prepare all 9 register reads in parallel
const reads = [
    { name: 'runState', address: 600, quantity: 1 },
    { name: 'commBoard', address: 648, quantity: 1 },
    { name: 'warning1', address: 653, quantity: 1 },
    { name: 'warning2', address: 654, quantity: 1 },
    { name: 'fault1', address: 655, quantity: 1 },
    { name: 'fault2', address: 656, quantity: 1 },
    { name: 'fault3', address: 657, quantity: 1 },
    { name: 'fault4', address: 658, quantity: 1 },
    { name: 'workFlag', address: 659, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name,
    registerAddress: r.address
}));

return [messages];

const flowKey = 'alarm_state_reads';
let collected = flow.get(flowKey) || {};
const expectedCount = 9;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const value = data[0] || 0;

// Store by register address for clarity
switch(msg.readName) {
    case 'runState':
        collected.runStateRaw = value;
        break;
    case 'commBoard':
        collected.commBoardFaultRaw = value;
        break;
    case 'warning1':
        collected.warningWord1Raw = value;
        break;
    case 'warning2':
        collected.warningWord2Raw = value;
        break;
    case 'fault1':
        collected.faultWord1Raw = value;
        break;
    case 'fault2':
        collected.faultWord2Raw = value;
        break;
    case 'fault3':
        collected.faultWord3Raw = value;
        break;
    case 'fault4':
        collected.faultWord4Raw = value;
        break;
    case 'workFlag':
        collected.workFlagTripData = value;
        break;
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";
const now = new Date().toISOString();

const activeAlarms = [];

// Helper function to add alarm
function addAlarm(code, vendorCode, severity, category) {
    if (vendorCode > 0) {
        activeAlarms.push({
            code: code,
            vendorCode: vendorCode,
            severity: severity,
            sourceDevice: "inverter",
            category: category,
            messageKey: `${category}_${code}`,
            messageParams: null,
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        });
    }
}

// Check warnings (653-654)
addAlarm(653, data.warningWord1Raw, "WARNING", "warning");
addAlarm(654, data.warningWord2Raw, "WARNING", "warning");

// Check faults (655-658)
addAlarm(655, data.faultWord1Raw, "ERROR", "fault");
addAlarm(656, data.faultWord2Raw, "ERROR", "fault");
addAlarm(657, data.faultWord3Raw, "ERROR", "fault");
addAlarm(658, data.faultWord4Raw, "ERROR", "fault");

// Check comm board fault (648)
addAlarm(648, data.commBoardFaultRaw, "ALARM", "comm_fault");

const state = {
    kind: "InverterAlarmState",
    timestampUtc: now,
    version: 1,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    runStateRaw: data.runStateRaw,
    commBoardFaultRaw: data.commBoardFaultRaw,

    warningWord1Raw: data.warningWord1Raw,
    warningWord2Raw: data.warningWord2Raw,

    faultWord1Raw: data.faultWord1Raw,
    faultWord2Raw: data.faultWord2Raw,
    faultWord3Raw: data.faultWord3Raw,
    faultWord4Raw: data.faultWord4Raw,

    workFlagTripData: data.workFlagTripData,

    activeAlarms: activeAlarms
};

msg.payload = state;
msg.state = state;
msg.hasAlarms = activeAlarms.length > 0;

node.status({ 
    fill: activeAlarms.length > 0 ? "red" : "green", 
    shape: "dot", 
    text: `${activeAlarms.length} alarm(s)` 
});

return msg;

// Only send to ThingsBoard if there are active alarms
if (msg.hasAlarms) {
    node.status({ fill: "red", shape: "dot", text: "Sending alarms" });
    return msg;
}

node.status({ fill: "green", shape: "dot", text: "No alarms - skipped" });
return null;

// Register 217: lowBatteryCapacityPercent
// Register 688: socPercent

const reads = [
    { name: 'lowBatteryCapacity', address: 217, quantity: 1 },
    { name: 'socPercent', address: 688, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name,
    registerAddress: r.address
}));

return [messages];

const flowKey = 'lowsoc_reads';
let collected = flow.get(flowKey) || {};
const expectedCount = 2;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const value = data[0] || 0;

switch(msg.readName) {
    case 'lowBatteryCapacity':
        collected.lowBatteryCapacityPercent = value;
        break;
    case 'socPercent':
        collected.socPercent = value;
        break;
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const lowBatteryCapacityPercent = data.lowBatteryCapacityPercent;
const socPercent = data.socPercent;

if (lowBatteryCapacityPercent === undefined || socPercent === undefined) {
    node.status({ fill: "red", shape: "dot", text: "Missing values" });
    return null;
}

// Get last sent SOC from flow context
let lastSentLowBatterySoc = flow.get("lastSentLowBatterySoc");

// Initialize if first run
if (lastSentLowBatterySoc === null || lastSentLowBatterySoc === undefined) {
    lastSentLowBatterySoc = lowBatteryCapacityPercent;
    flow.set("lastSentLowBatterySoc", lastSentLowBatterySoc);
    node.status({ fill: "blue", shape: "dot", text: "Init: " + lastSentLowBatterySoc });
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";
const now = new Date().toISOString();

let shouldSend = false;
let triggeredAtStep = null;

// Check if SOC is below threshold
if (socPercent < lowBatteryCapacityPercent) {
    // Calculate current step (round down to nearest 5)
    let currentStep = Math.floor(socPercent / 5) * 5;

    // Check if we should send (new step lower than last sent)
    if (currentStep < lastSentLowBatterySoc) {
        shouldSend = true;
        triggeredAtStep = currentStep;
        flow.set("lastSentLowBatterySoc", currentStep);
        node.status({ fill: "yellow", shape: "dot", text: "ALARM: SOC=" + socPercent + " step=" + currentStep });
    } else {
        node.status({ fill: "grey", shape: "ring", text: "Skip: SOC=" + socPercent + " step=" + currentStep + " last=" + lastSentLowBatterySoc });
    }
} else {
    // SOC is above threshold, reset
    if (lastSentLowBatterySoc !== lowBatteryCapacityPercent) {
        flow.set("lastSentLowBatterySoc", lowBatteryCapacityPercent);
        node.status({ fill: "green", shape: "dot", text: "Reset: SOC=" + socPercent + " >= " + lowBatteryCapacityPercent });
    } else {
        node.status({ fill: "green", shape: "ring", text: "OK: SOC=" + socPercent });
    }
}

msg.shouldSend = shouldSend;

if (shouldSend) {
    const state = {
        kind: "InverterAlarmState",
        timestampUtc: now,
        version: 1,
        gatewayId: gatewayId,
        inverterSerialNumber: inverterSN,

        runStateRaw: null,
        commBoardFaultRaw: null,
        warningWord1Raw: null,
        warningWord2Raw: null,
        faultWord1Raw: null,
        faultWord2Raw: null,
        faultWord3Raw: null,
        faultWord4Raw: null,
        workFlagTripData: null,

        activeAlarms: [{
            code: 11,
            vendorCode: 11,
            severity: "WARNING",
            sourceDevice: "INV",
            category: "battery",
            messageKey: "W11",
            messageParams: {
                currentSocPercent: socPercent
            },
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        }]
    };

    msg.payload = state;
    msg.state = state;
}

return msg;

// Only send if shouldSend is true
if (msg.shouldSend) {
    node.status({ fill: "red", shape: "dot", text: "Sending W11 alarm" });
    return msg;
}

node.status({ fill: "green", shape: "dot", text: "No alarm - skipped" });
return null;
